class Allergies:

    ALLERGENS = {
        "eggs": 1,
        "peanuts": 2,
        "shellfish": 4,
        "strawberries": 8,
        "tomatoes": 16,
        "chocolate": 32,
        "pollen": 64,
        "cats": 128,
    }

    def __init__(self, score):
        self.score = score

    def allergic_to(self, item):
        if item not in self.ALLERGENS:
            # If the item is not a known allergen, the person cannot be allergic to it based on this test.
            return False

        item_value = self.ALLERGENS[item]
        # Use bitwise AND to check if the item's bit is set in the score.
        # If (score & item_value) is non-zero, it means the person is allergic.
        return (self.score & item_value) != 0

    @property
    def lst(self):
        allergies_list = []
        # Iterate through allergens sorted by their value to get a consistent order.
        # This also ensures we only consider the listed allergens and ignore higher bits.
        for allergen_name, allergen_value in sorted(self.ALLERGENS.items(), key=lambda item: item[1]):
            if (self.score & allergen_value) != 0:
                allergies_list.append(allergen_name)
        return allergies_list
